        "terminates_state_refs": [
          "ST_cohesin_holding_sister_chromatids",
          "ST_duplicated_chromosome_aligned_at_metaphase_plate"
        ],
        "observables": [
          {
            "constraint_id": "OBS_connection_breakdown_after_alignment",
            "predicate": "event_precedes",
            "ordered_process_ids": [
              "PROC_metaphase_alignment",
              "PROC_anaphase_sister_separation"
            ],
            "capability": "PARTIAL",
            "evidence_ids": ["E_dcb0de9a22b0"],
            "support": [
              {
                "evidence_id": "E_dcb0de9a22b0",
                "quote": "In anaphase, the connection between the sister chromatids breaks down, and the microtubules pull the chromosomes toward opposite poles.",
                "location": "paragraph_28"
              }
            ]
          },
          {
            "constraint_id": "OBS_two_daughter_chromatids_after_separation",
            "predicate": "state_transition_allowed",
            "state_key": "sister_chromatid_attachment",
            "to_value": "broken down",
            "precondition": {
              "metaphase_alignment": "Duplicated chromosome aligned at metaphase plate (schematic phase order).",
              "cohesin_present_prior": "Sister chromatids still tightly attached by cohesin proteins prior to anaphase."
            },
            "capability": "PARTIAL",
            "evidence_ids": ["E_dcb0de9a22b0"],
            "support": [
              {
                "evidence_id": "E_dcb0de9a22b0",
                "quote": "Each chromatid, now called a chromosome, is pulled rapidly toward the centrosome to which its microtubule is attached.",
                "location": "paragraph_30"
              }
            ]
          }
        ],
        "exceptions": [
          {
            "note": "Source also states 'the cohesin proteins degrade' (paragraph_30); this molecular mechanism is acknowledged but deliberately not modeled as a causal agent. The process asserts only the observable breakdown and separation; no causal sufficiency of microtubule pulling alone is claimed."
          }
        ]
      }
    }
  ],
